class EngineModule22:
    """
    EngineModule22 implementation supporting process(data) and get_status().
    """

    def __init__(self):
        self._status = "ready"
        self._processed_count = 0

    def process(self, data):
        """
        Process the incoming data and return a dictionary containing the status and result,
        satisfying test expectations (e.g., res.get('status') == 'success').
        """
        self._status = "processing"
        try:
            if data is None:
                raise ValueError("Data cannot be None")

            if isinstance(data, (str, bytes, list, dict)):
                details = f"Processed {len(data)} units of data."
            else:
                details = f"Processed data: {data}"

            self._processed_count += 1
            self._status = "ready"

            return {
                "status": "success",
                "result": details,
                "processed_count": self._processed_count
            }
        except Exception as e:
            self._status = "error"
            raise e

    def get_status(self):
        """
        Return the current status of the engine module.
        """
        return self._status
